package org.sleepwell.app;
import org.junit.Test;import static org.junit.Assert.*;
/** Real pause rows and per-session active duration using the production gesture owner and fake ports. */
public final class TrackingFlipStorageTest {
 static final class Run implements TrackingFlipSession.Effects,AutoCloseable{final Store store;final TrackingFlipFixture.Fake port=new TrackingFlipFixture.Fake();final TrackingClock clock;final long id,start,origin;final TrackingFlipSession owner;long now,pauseWall;boolean live=true;int resumes,pauses;Run(TrackingFlipFixture f)throws Exception{store=new Store(f.c,f.database);id=store.begin();start=store.rows("SELECT start FROM sessions WHERE id=?",""+id).get(0).getLong("start");now=origin=port.now;clock=new TrackingClock(now/1000000);owner=new TrackingFlipSession(port,this,()->now);}public boolean current(){return live;}public void pause(){pauses++;long wall=pauseWall=timestamp();clock.pause(now/1000000);store.pause(id,wall);owner.paused();}public void resume(){resumes++;store.resume(id,timestamp());clock.resume(now/1000000);owner.active();}long timestamp(){return clock.timestamp(start,now/1000000);}void pose(double z,int count){for(int n=0;n<count;n++){now+=100000000;TrackingFlipSession.Sink sink=port.sink;if(sink!=null)sink.sample(now,now,0,0,z,true);}}void flip(){pose(9.8,12);pose(-9.8,14);}public void close(){owner.close();store.close();}}
 @Test public void realFiveMinutePauseRetainsSingleSessionAndExcludesOnlyItsGap()throws Exception{try(TrackingFlipFixture f=new TrackingFlipFixture();Run r=new Run(f)){assertEquals(0,r.port.starts);r.owner.active();r.flip();assertEquals(1,r.pauses);assertEquals(TrackingFlipSession.State.PAUSED,r.owner.state);long pause=r.store.rows("SELECT start FROM tracking_pauses").get(0).getLong("start");assertEquals("Pause starts at the accepted gesture callback, not a later orientation sample",r.pauseWall,pause);assertTrue(r.timestamp()>=pause);assertTrue(r.store.rows("SELECT * FROM epochs").isEmpty());r.now=r.owner.deadline*1000000;r.owner.tick();assertEquals(1,r.resumes);assertEquals(TrackingFlipSession.State.ACTIVE,r.owner.state);assertEquals(1,r.store.rows("SELECT * FROM sessions").size());assertEquals(r.id,r.store.rows("SELECT id FROM sessions").get(0).getLong("id"));long end=r.store.rows("SELECT end FROM tracking_pauses").get(0).getLong("end");assertEquals(300000,end-pause);r.now+=1000000000;r.store.end(r.id,false,r.clock.active(r.now/1000000),r.timestamp());org.json.JSONObject saved=r.store.rows("SELECT * FROM sessions").get(0);assertEquals(300000,saved.getLong("end")-saved.getLong("start")-saved.getLong("active_ms"));assertEquals(SensorProvenance.MOTION,saved.getString("sensor"));assertTrue(r.store.rows("SELECT * FROM sound_events").isEmpty());}}
 @Test public void faceUpResumeUsesSameDurablePauseAndDoesNotCreateMeasurements()throws Exception{try(TrackingFlipFixture f=new TrackingFlipFixture();Run r=new Run(f)){r.owner.active();r.flip();r.pose(-9.8,12);r.pose(9.8,14);assertEquals(1,r.resumes);assertEquals(1,r.store.rows("SELECT * FROM sessions").size());org.json.JSONObject gap=r.store.rows("SELECT * FROM tracking_pauses").get(0);assertTrue(gap.getLong("end")>gap.getLong("start"));assertTrue(gap.getLong("end")-gap.getLong("start")<300000);assertTrue(r.store.rows("SELECT * FROM epochs").isEmpty());assertTrue(r.store.rows("SELECT * FROM clips").isEmpty());}}
 @Test public void manualPauseAndClosedOwnerCannotFillOrReopenGap()throws Exception{try(TrackingFlipFixture f=new TrackingFlipFixture();Run r=new Run(f)){r.owner.active();r.flip();long due=r.owner.deadline;r.owner.manualPause();r.now=(due+1000)*1000000;r.owner.tick();assertEquals(0,r.resumes);assertTrue(r.store.rows("SELECT end FROM tracking_pauses").get(0).isNull("end"));r.live=false;r.owner.close();r.live=true;r.owner.tick();assertEquals(0,r.resumes);assertEquals(1,r.store.rows("SELECT * FROM sessions").size());assertTrue(r.store.rows("SELECT * FROM epochs").isEmpty());}}
}
